export const serviceIcon=slug=>`<svg class="service-icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${iconPaths[slug]||iconPaths['balkon-pod-klyuch']}</svg>`;
const pictureAsset=(name,suffix='')=>{const match=name.match(/^(.*)(\.[^.]+)$/);return match?`${match[1]}${suffix}${match[2]}`:`${name}${suffix}.webp`;};
const serviceImage=s=>`<img src="/assets/${pictureAsset(s.image)}" width="960" height="640" loading="lazy" decoding="async" alt="${esc(`${s.title} — фотография услуги ArtBalkon`)}">`;
export const button=(label,href='#quiz',extra='')=>`<a class="button ${extra}" href="${href}">${label} ${buttonArrow}</a>`;
export function pic(name,alt,classes='',eager=false){const src=pictureAsset(name);const small=pictureAsset(name,'-small');return `<img class="${classes}" src="/assets/${src}" srcset="/assets/${small} 480w, /assets/${src} 1000w" sizes="(max-width: 640px) calc(100vw - 40px), (max-width: 1000px) 50vw, 600px" width="1000" height="1100" loading="${eager?'eager':'lazy'}" ${eager?'fetchpriority="high"':''} decoding="async" alt="${esc(alt)}">`;}
