const serviceHeroSlideshow=service=>{
 const slides=[service.image,...(serviceHeroSlides[service.slug]||[])].filter((name,index,list)=>list.indexOf(name)===index);
 return `<div class="landing-photo hero-slideshow" data-hero-slider>${slides.map((name,index)=>index===0
  ?pic(name,`${service.title} — фотография из портфолио ArtBalkon`,'hero-image is-active',true)
  :`<img class="hero-image" src="/assets/${pictureAsset(name)}" width="1000" height="1100" loading="lazy" decoding="async" aria-hidden="true" alt="${esc(`${service.title} — пример готового решения ArtBalkon`)}">`).join('')}</div>`;
};
export const brand=`<a class="brand" href="/" aria-label="ArtBalkon — главная"><img class="brand-logo" src="/assets/artbalkon-logo.svg" width="461" height="132" alt="ArtBalkon"></a>`;
const headerMessengers=extra=>`<div class="header-messengers ${extra||''}" aria-label="Написать в мессенджер"><a class="header-messenger telegram-messenger" href="${company.telegram}" target="_blank" rel="noopener" data-event="telegram_click" aria-label="Написать в Telegram"><img src="/assets/telegram-logo.svg" width="128" height="128" alt="Telegram"></a><a class="header-messenger max-messenger" href="${company.max}" target="_blank" rel="noopener" aria-label="Написать в MAX"><img src="/assets/max-app-icon.png" width="250" height="250" alt="MAX"></a></div>`;
