const headerNavigation=path=>{
 if(path==='/')return [['Главная','/'],['Услуги','#services'],['Наши работы','#before-after'],['Отзывы','#reviews'],['Контакты','#contacts']];
 if(services.some(service=>path===`/${service.slug}/`))return [['Главная','/'],['Наши работы','#before-after'],['Отзывы','#reviews'],['Контакты','#contacts']];
 if(path==='/nashi-raboty/')return [['Главная','/'],['Наши работы','/#before-after'],['Рассчитать стоимость','#quiz'],['Контакты','#contacts']];
 if(path.startsWith('/nashi-raboty/'))return [['Главная','/'],['Все работы','/nashi-raboty/'],['Рассчитать стоимость','#quiz'],['Контакты','#contacts']];
 return [['Главная','/'],['Наши работы','/#before-after'],['Рассчитать стоимость','#quiz']];
};
const headerNavigationMarkup=items=>items.map(([label,href])=>`<a href="${href}">${label}</a>`).join('');
export function header(path='/'){
 const navigation=headerNavigation(path),navigationMarkup=headerNavigationMarkup(navigation),callbackHref=['/privacy/','/consent/','/404.html'].includes(path)?'/#callback':'#callback';
 return `<a class="skip-link" href="#main">Перейти к содержанию</a><header class="site-header"><div class="container header-inner">${brand}<nav class="desktop-nav" aria-label="Основная навигация">${navigationMarkup}</nav><div class="header-contact"><a class="phone" data-event="phone_click" href="tel:${company.tel}">${company.phone}</a>${headerMessengers()}</div>${button('Заказать звонок',callbackHref,'button-small header-cta')}<button class="menu-toggle" aria-label="Открыть меню" aria-expanded="false" aria-controls="mobile-menu"><span></span><span></span><span></span></button></div><div class="mobile-menu-backdrop" data-mobile-menu-close hidden></div><nav id="mobile-menu" class="mobile-menu" aria-label="Мобильная навигация" hidden><div class="mobile-menu-head">${brand}<button class="mobile-menu-close" type="button" data-mobile-menu-close aria-label="Закрыть меню">×</button></div><div class="mobile-menu-links">${navigationMarkup}</div><div class="mobile-menu-contact"><a class="mobile-menu-phone" data-event="phone_click" href="tel:${company.tel}">${company.phone}</a>${headerMessengers('mobile-menu-messengers')}</div>${button('Заказать звонок',callbackHref)}<p class="mobile-menu-note">Остекление, утепление и отделка балконов и лоджий в Москве и области</p></nav></header>`;
}
